/**
 * Busca una especie por ID o nombre. Si no existe, genera una especie compatible estándar.
 */
export function findSpeciesById(id: number): Species {
  const found = POKEMON_SPECIES_LIST.find((s) => s.id === id);
  if (found) {
    return found;
  }
  return {
    id,
    name: `Pokémon ${id}`,
    genderRatio: 0.5,
    eggGroups: [{ name: 'Field' }],
    gen: 1,
    baseStats: { hp: 50, attack: 50, defense: 50, spatk: 50, spdef: 50, speed: 50 },
    captureRate: 45,
  };
}

/**
 * Busca una especie por su nombre (búsqueda insensible a mayúsculas).
 */
export function findSpeciesByName(name: string): Species | undefined {
  const trimmed = name.trim().toLowerCase();
  return POKEMON_SPECIES_LIST.find((s) => s.name.toLowerCase() === trimmed);
}

